import { NextResponse } from 'next/server';
import { runFullHealthCheck } from '@/lib/test-engine';
import clientPromise from '@/lib/mongodb';

export const dynamic = 'force-dynamic';

export async function POST(request: Request) {
    // 9-second fail-safe for Vercel Hobby (10s limit)
    const GLOBAL_TIMEOUT_MS = 9000;
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), GLOBAL_TIMEOUT_MS);

    try {
        const body = await request.json();
        const { domain } = body;

        if (!domain || typeof domain !== 'string' || !domain.includes('.')) {
            return NextResponse.json({ error: 'Invalid domain format' }, { status: 400 });
        }

        const cleanDomain = domain.trim().toLowerCase();

        // 1. RUN ORIGINAL TEST LOGIC (Exactly as it was)
        // This ensures HTTP and internal timeouts are handled by the engine normally
        const healthReport = await Promise.race([
            runFullHealthCheck(cleanDomain),
            new Promise<never>((_, reject) =>
                setTimeout(() => reject(new Error('Global Timeout')), GLOBAL_TIMEOUT_MS - 500)
            )
        ]);

        // 2. FETCH MONGODB EMAIL (Simple, separate step)
        let dbEmail = null;
        try {
            const client = await clientPromise;
            // Database: "vercel", Collection: "dfyinfrasetups" (from your screenshot)
            const db = client.db("vercel");
            const collection = db.collection("dfyinfrasetups");

            // Search for the domain (case-insensitive)
            const doc = await collection.findOne({
                domain: { $regex: new RegExp(`^${cleanDomain}$`, "i") }
            });

            if (doc) {
                // Priority: 'user' field, then first contact email
                dbEmail = (doc as any).user || (doc as any).contactDetails?.[0]?.email || null;
            }
        } catch (mongoError) {
            console.error("MongoDB fetch failed (optional):", mongoError);
        }

        return NextResponse.json({
            ...healthReport,
            dbEmail: dbEmail
        });

    } catch (error: any) {
        if (error.message === 'Global Timeout' || error.name === 'AbortError') {
            return NextResponse.json({
                error: 'Timeout',
                message: 'The health check exceeded execution limits. Please try again.',
                status: 'partial'
            }, { status: 200 });
        }
        console.error('API Error:', error);
        return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
    } finally {
        clearTimeout(timeoutId);
    }
}

import { NextRequest, NextResponse } from 'next/server';
import clientPromise from '@/lib/mongodb';
import * as xlsx from 'xlsx';
import { isAdmin } from '@/lib/roles';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
    try {
        const searchParams = request.nextUrl.searchParams;
        const email = searchParams.get('email');

        if (!(await isAdmin(email))) {
            return new NextResponse('Unauthorized access', { status: 403 });
        }

        const issueFilter = searchParams.get('filter') || 'All';
        const query = searchParams.get('query') || '';

        const client = await clientPromise;
        const db = client.db('vercel');
        const collection = db.collection('issue_domains');

        const filter: any = {};

        if (query) {
            filter.domain = { $regex: query, $options: 'i' };
        }

        if (issueFilter && issueFilter !== 'All') {
            filter.issueCategory = issueFilter;
        } else {
            filter.issueCategory = { $ne: 'Needs_Scan' };
        }

        // Fetch all matching domains for the report
        const domains = await collection.find(filter).sort({ domain: 1 }).toArray();

        // Format data for Excel
        const data = domains.map(d => ({
            Domain: d.domain,
            Status: d.status,
            'Issue Category': d.issueCategory || 'Clean',
            'Issues Detected': d.issuesDetected,
            'User': d.user || 'Unassigned',
            'SPF Record': d.updatedSpfFull || d.spfFull || 'N/A',
            'DMARC Record': d.updatedDmarcFull || d.dmarcFull || 'N/A',
            'Last Scanned': d.timestamp ? new Date(d.timestamp).toISOString() : 'Unknown'
        }));

        if (data.length === 0) {
            // Provide an empty sheet with headers if no results
            data.push({
                Domain: 'No domains matched the filter.',
                Status: '',
                'Issue Category': '',
                'Issues Detected': 0,
                'User': '',
                'SPF Record': '',
                'DMARC Record': '',
                'Last Scanned': ''
            } as any);
        }

        // Generate Excel Workbook
        const worksheet = xlsx.utils.json_to_sheet(data);

        // Add padding / column widths for better aesthetics
        worksheet['!cols'] = [
            { wch: 40 }, // Domain
            { wch: 15 }, // Status
            { wch: 25 }, // Issue Category
            { wch: 18 }, // Issues Detected
            { wch: 25 }, // User
            { wch: 60 }, // SPF Record
            { wch: 60 }, // DMARC Record
            { wch: 30 }  // Last Scanned
        ];

        const workbook = xlsx.utils.book_new();
        xlsx.utils.book_append_sheet(workbook, worksheet, "Fleet Report");

        // Write to buffer
        const buffer = xlsx.write(workbook, { type: 'buffer', bookType: 'xlsx' });

        const filename = `DomainGuard_Report_${issueFilter === 'All' ? 'Full_Fleet' : issueFilter}.xlsx`;

        return new NextResponse(buffer, {
            status: 200,
            headers: {
                'Content-Disposition': `attachment; filename="${filename}"`,
                'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
            }
        });

    } catch (error) {
        console.error('Error generating report:', error);
        return NextResponse.json({ error: 'Failed to generate report' }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from 'next/server';
import clientPromise from '@/lib/mongodb';

export async function POST(request: NextRequest) {
    try {
        // Authenticate the webhook request
        const authHeader = request.headers.get('Authorization');
        // You should set a WEBHOOK_SECRET in your .env.local
        const EXPECTED_SECRET = process.env.WEBHOOK_SECRET;

        if (authHeader !== `Bearer ${EXPECTED_SECRET}`) {
            return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
        }

        const body = await request.json();

        // Validate required fields
        if (!body.domain || !body.status || !body.issueCategory) {
            return NextResponse.json({ error: 'Missing required fields: domain, status, issueCategory' }, { status: 400 });
        }

        const client = await clientPromise;
        const db = client.db();
        const collection = db.collection('issue_domains');

        // Construct the update document matching the exact schema from Excel
        const updateDoc: any = {
            $set: {
                domain: body.domain,
                user: body.user || null,
                score: body.score !== undefined ? body.score : null,
                healthStatus: body.healthStatus || null,
                status: body.status, // "Secure" or "At Risk"
                issueCategory: body.issueCategory || 'Clean', // e.g. "No_SPF_AND_DMARC"
                spfFull: body.spfFull || null,
                updatedSpfFull: body.updatedSpfFull || null,
                dmarcFull: body.dmarcFull || null,
                updatedDmarcFull: body.updatedDmarcFull || null,
                issuesDetected: body.issuesDetected || 0,
                timestamp: new Date() // Always update the timestamp when automation runs
            }
        };

        // If the python script passes specific issues (blacklist, dns, etc)
        if (body.issues) {
            updateDoc.$set.issues = body.issues;
        }

        // Upsert the domain document
        const result = await collection.updateOne(
            { domain: body.domain },
            updateDoc,
            { upsert: true }
        );

        return NextResponse.json({
            success: true,
            message: 'Domain updated successfully',
            upsertedId: result.upsertedId,
            modifiedCount: result.modifiedCount
        }, { status: 200 });

    } catch (error) {
        console.error('Webhook error:', error);
        return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }
}

'use server';

import clientPromise from '@/lib/mongodb';
import { encryptApiKey, decryptApiKey } from '@/lib/encryption';
import { randomUUID } from 'crypto';

export interface Integration {
    id: string;
    email: string; // The user who owns this integration
    provider: 'cloudflare';
    label: string;
    encryptedApiKey: string;
    createdAt: Date;
    updatedAt: Date;
}

// DTO for frontend so we never send the API key back, even encrypted
export interface IntegrationDTO {
    id: string;
    provider: 'cloudflare';
    label: string;
    createdAt: Date;
}

export async function addIntegration(email: string, provider: 'cloudflare', label: string, apiKey: string) {
    if (!email || !apiKey || !label) {
        return { success: false, error: "Missing required fields" };
    }

    try {
        const client = await clientPromise;
        const db = client.db('vercel');
        const collection = db.collection<Integration>('integrations');

        const encryptedApiKey = encryptApiKey(apiKey);

        const newIntegration: Integration = {
            id: randomUUID(),
            email,
            provider,
            label,
            encryptedApiKey,
            createdAt: new Date(),
            updatedAt: new Date()
        };

        await collection.insertOne(newIntegration);

        return { success: true };
    } catch (error) {
        console.error("Error adding integration:", error);
        return { success: false, error: "Failed to add integration securely" };
    }
}

export async function getUserIntegrations(email: string): Promise<{ success: boolean; integrations?: IntegrationDTO[]; error?: string }> {
    if (!email) {
        return { success: false, error: "Email required" };
    }

    try {
        const client = await clientPromise;
        const db = client.db('vercel');
        const collection = db.collection<Integration>('integrations');

        const integrations = await collection.find({ email }).sort({ createdAt: -1 }).toArray();

        // Strip sensitive data before sending to frontend
        const dtos: IntegrationDTO[] = integrations.map(int => ({
            id: int.id,
            provider: int.provider,
            label: int.label,
            createdAt: int.createdAt
        }));

        return { success: true, integrations: dtos };
    } catch (error) {
        console.error("Error fetching user integrations:", error);
        return { success: false, error: "Failed to fetch integrations" };
    }
}

export async function removeIntegration(email: string, integrationId: string) {
    if (!email || !integrationId) {
        return { success: false, error: "Missing required fields" };
    }

    try {
        const client = await clientPromise;
        const db = client.db('vercel');
        const collection = db.collection<Integration>('integrations');

        // Only allow removing if they own it
        const result = await collection.deleteOne({ id: integrationId, email });

        if (result.deletedCount === 1) {
            return { success: true };
        } else {
            return { success: false, error: "Integration not found or unauthorized" };
        }
    } catch (error) {
        console.error("Error removing integration:", error);
        return { success: false, error: "Failed to remove integration" };
    }
}

'use client';

import { useState, useEffect } from 'react';
import { auth } from '@/lib/firebase';
import { onAuthStateChanged, User } from 'firebase/auth';
import { useRouter } from 'next/navigation';
import { Navbar } from '@/components/Navbar';
import { Save, Mail, User as UserIcon, MessageSquare, Loader2, ArrowLeft, CheckCircle2, Shield, Plus, Trash2, ChevronDown, ChevronUp, X } from 'lucide-react';
import { getUserSettings, saveUserSettings } from '@/app/settings/actions';
import { getUserIntegrations, addIntegration, removeIntegration, IntegrationDTO } from '@/app/settings/integrations-actions';
import { UserSettings, DEFAULT_SETTINGS } from '@/app/settings/types';
import { isAdmin, getAdmins, addAdmin, removeAdmin, AdminUser } from '@/lib/roles';

export default function SettingsPage() {
    const [user, setUser] = useState<User | null | undefined>(undefined);
    const [isUserAdmin, setIsUserAdmin] = useState(false);
    const router = useRouter();

    const [settings, setSettings] = useState<UserSettings>(DEFAULT_SETTINGS);
    const [initialSettings, setInitialSettings] = useState<UserSettings | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [saveMessage, setSaveMessage] = useState({ text: '', isError: false });

    // Admin array state
    const [adminUsers, setAdminUsers] = useState<AdminUser[]>([]);
    const [newAdminEmails, setNewAdminEmails] = useState<string[]>([]);
    const [adminInputValue, setAdminInputValue] = useState('');
    const [isManagingAdmins, setIsManagingAdmins] = useState(false);
    const [isAccessMgmtOpen, setIsAccessMgmtOpen] = useState(false);

    // Integrations state
    const [integrations, setIntegrations] = useState<IntegrationDTO[]>([]);
    const [integrationLabel, setIntegrationLabel] = useState('');
    const [integrationApiKey, setIntegrationApiKey] = useState('');
    const [isManagingIntegrations, setIsManagingIntegrations] = useState(false);

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
            if (currentUser === null) {
                router.push('/');
                return;
            }
            setUser(currentUser);

            if (currentUser.email) {
                const adminStatus = await isAdmin(currentUser.email);
                setIsUserAdmin(adminStatus);

                const res = await getUserSettings(currentUser.email);
                if (res.success && res.settings) {
                    setSettings(res.settings);
                    setInitialSettings(res.settings);
                }

                if (adminStatus) {
                    const adminsList = await getAdmins();
                    setAdminUsers(adminsList);
                }

                const intsRes = await getUserIntegrations(currentUser.email);
                if (intsRes.success && intsRes.integrations) {
                    setIntegrations(intsRes.integrations);
                }
            } else {
                setIsUserAdmin(false);
            }
            setIsLoading(false);
        });

        return () => unsubscribe();
    }, [router]);

    const handleSave = async () => {
        if (!user || !user.email) return;

        setIsSaving(true);
        setSaveMessage({ text: '', isError: false });

        const res = await saveUserSettings(user.email, settings);

        if (res.success) {
            setInitialSettings(settings); // Changes are now saved, reset baseline
            setSaveMessage({ text: 'Settings saved successfully!', isError: false });
            // Dispatch event to trigger navbar to update its display name
            window.dispatchEvent(new Event('user-settings-updated'));
        } else {
            setSaveMessage({ text: 'Failed to save settings.', isError: true });
        }

        setIsSaving(false);

        // Clear success message after 3 seconds
        setTimeout(() => {
            setSaveMessage({ text: '', isError: false });
        }, 3000);
    };

    const handleAddAdmin = async (e?: React.FormEvent) => {
        if (e) e.preventDefault();

        const emailsToProcess = [...newAdminEmails];
        // If there's an active typed email not yet tokenized, try to add it
        if (adminInputValue.trim()) {
            const val = adminInputValue.trim().toLowerCase();
            // Basic email regex before processing
            if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val) && !emailsToProcess.includes(val)) {
                emailsToProcess.push(val);
            }
        }

        if (emailsToProcess.length === 0 || !user?.email) return;

        setIsManagingAdmins(true);
        let successCount = 0;
        let lastError = '';

        for (const email of emailsToProcess) {
            const res = await addAdmin(email, user.email);
            if (res.success) {
                successCount++;
            } else {
                lastError = res.message || `Failed to add ${email}.`;
            }
        }

        if (successCount > 0) {
            setSaveMessage({ text: `Successfully added ${successCount} admin(s).`, isError: false });
            setNewAdminEmails([]);
            setAdminInputValue('');
            const adminsList = await getAdmins();
            setAdminUsers(adminsList);
        } else if (lastError) {
            setSaveMessage({ text: lastError, isError: true });
        }

        setIsManagingAdmins(false);
        setTimeout(() => setSaveMessage({ text: '', isError: false }), 3000);
    };

    const handleEmailInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Enter' || e.key === ' ' || e.key === ',') {
            e.preventDefault();
            const val = adminInputValue.trim().toLowerCase();
            if (val && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val)) {
                if (!newAdminEmails.includes(val)) {
                    setNewAdminEmails([...newAdminEmails, val]);
                }
                setAdminInputValue('');
            }
        } else if (e.key === 'Backspace' && !adminInputValue && newAdminEmails.length > 0) {
            e.preventDefault();
            // Remove the last token on backspace if input is empty
            const lastEmail = newAdminEmails[newAdminEmails.length - 1];
            setNewAdminEmails(newAdminEmails.slice(0, -1));
            setAdminInputValue(lastEmail);
        }
    };

    const removeEmailToken = (email: string) => {
        setNewAdminEmails(newAdminEmails.filter(e => e !== email));
    };

    const handleRemoveAdmin = async (emailToRemove: string) => {
        if (!user?.email || !confirm(`Are you sure you want to revoke admin access for ${emailToRemove}?`)) return;

        setIsManagingAdmins(true);
        const res = await removeAdmin(emailToRemove, user.email);

        if (res.success) {
            setSaveMessage({ text: 'Admin removed successfully.', isError: false });
            const adminsList = await getAdmins();
            setAdminUsers(adminsList);
        } else {
            setSaveMessage({ text: res.message || 'Failed to remove admin.', isError: true });
        }
        setIsManagingAdmins(false);
        setTimeout(() => setSaveMessage({ text: '', isError: false }), 3000);
    };

    const handleAddIntegration = async (e: React.FormEvent) => {
