interface LoginModalProps {
    isOpen: boolean;
    onClose: () => void;
}

export function LoginModal({ isOpen, onClose }: LoginModalProps) {
    const [isLogin, setIsLogin] = useState(true);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [name, setName] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError(null);

        try {
            if (isLogin) {
                await signInWithEmailAndPassword(auth, email, password);
                // Sync user profile on login too, just in case
                if (auth.currentUser) await saveUserProfile(auth.currentUser);
            } else {
                // Sign Up Logic
                const cred = await createUserWithEmailAndPassword(auth, email, password);
                if (name) {
                    await updateProfile(cred.user, { displayName: name });
                }
                // Sync to Database
                await saveUserProfile(cred.user);
            }
            onClose();
        } catch (err: any) {
            const firebaseError = err as AuthError;
            console.error(firebaseError);
            let msg = 'An error occurred.';
            if (firebaseError.code === 'auth/invalid-credential') msg = 'Invalid email or password.';
            if (firebaseError.code === 'auth/email-already-in-use') msg = 'Email is already registered.';
            if (firebaseError.code === 'auth/weak-password') msg = 'Password should be at least 6 characters.';
            setError(msg);
        } finally {
            setLoading(false);
        }
    };

    // ... (existing imports)

    const handleGoogleLogin = async () => {
        setLoading(true);
        setError(null);
        try {
            const provider = new GoogleAuthProvider();
            const result = await signInWithPopup(auth, provider);
            await saveUserProfile(result.user);
            onClose();
        } catch (err: any) {
            console.error(err);
            setError("Google sign-in failed. Please try again.");
        } finally {
            setLoading(false);
        }
    };

    const toggleMode = () => {
        setIsLogin(!isLogin);
        setError(null);
        setPassword('');
    };

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title={isLogin ? 'Welcome Back' : 'Create Account'}
        >
            <div className="space-y-4">
                {/* Google Sign In Button */}
                <button
                    type="button"
                    onClick={handleGoogleLogin}
                    disabled={loading}
                    className="w-full py-2.5 bg-white dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 hover:bg-zinc-50 dark:hover:bg-zinc-700 text-zinc-900 dark:text-zinc-100 font-medium rounded-lg transition-all flex items-center justify-center gap-2 group cursor-pointer"
                >
                    <GoogleIcon className="w-5 h-5" />
                    <span>Continue with Google</span>
                </button>

                <div className="relative">
                    <div className="absolute inset-0 flex items-center">
                        <span className="w-full border-t border-zinc-200 dark:border-zinc-800" />
                    </div>
                    <div className="relative flex justify-center text-xs uppercase">
                        <span className="bg-white dark:bg-zinc-900 px-2 text-zinc-500">Or continue with email</span>
                    </div>
                </div>

                <form onSubmit={handleSubmit} className="space-y-4">
                    {error && (
                        <div className="p-3 rounded-lg bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 text-sm flex items-center gap-2">
                            <AlertCircle size={16} />
                            {error}
                        </div>
                    )}

                    {!isLogin && (
                        <div className="space-y-1">
                            <label className="text-xs font-medium text-zinc-500 uppercase">Name</label>
                            <div className="relative">
                                <UserIcon className="absolute left-3 top-2.5 text-zinc-400" size={18} />
                                <input
                                    type="text"
                                    required
                                    placeholder="Your Name"
                                    value={name}
                                    onChange={(e) => setName(e.target.value)}
                                    className="w-full pl-10 pr-4 py-2 border border-zinc-200 dark:border-zinc-800 rounded-lg bg-zinc-50 dark:bg-zinc-900/50 text-zinc-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all font-medium"
                                />
                            </div>
                        </div>
                    )}

                    <div className="space-y-1">
                        <label className="text-xs font-medium text-zinc-500 uppercase">Email</label>
                        <div className="relative">
                            <Mail className="absolute left-3 top-2.5 text-zinc-400" size={18} />
                            <input
                                type="email"
                                required
                                placeholder="you@company.com"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                className="w-full pl-10 pr-4 py-2 border border-zinc-200 dark:border-zinc-800 rounded-lg bg-zinc-50 dark:bg-zinc-900/50 text-zinc-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all font-medium"
                            />
                        </div>
                    </div>

                    <div className="space-y-1">
                        <label className="text-xs font-medium text-zinc-500 uppercase">Password</label>
                        <div className="relative">
                            <Lock className="absolute left-3 top-2.5 text-zinc-400" size={18} />
                            <input
                                type="password"
                                required
                                placeholder="•••••••"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="w-full pl-10 pr-4 py-2 border border-zinc-200 dark:border-zinc-800 rounded-lg bg-zinc-50 dark:bg-zinc-900/50 text-zinc-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all font-medium"
                            />
                        </div>
                    </div>

                    <button
                        type="submit"
                        disabled={loading}
                        className="w-full py-2.5 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg shadow-lg hover:shadow-blue-500/25 transition-all flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed cursor-pointer"
                    >
                        {loading ? (
                            <>
                                <Loader2 className="animate-spin" size={18} />
                                {isLogin ? 'Signing In...' : 'Creating Account...'}
                            </>
                        ) : (
                            isLogin ? 'Sign In' : 'Sign Up'
                        )}
                    </button>

                    <div className="pt-2 text-center text-sm text-zinc-500">
                        {isLogin ? "Don't have an account? " : "Already have an account? "}
                        <button
                            type="button"
                            onClick={toggleMode}
                            className="text-blue-600 hover:text-blue-700 font-medium hover:underline transition-all cursor-pointer"
                        >
                            {isLogin ? 'Sign up' : 'Log in'}
                        </button>
                    </div>
                </form>
            </div>
        </Modal>
    );
}

import React, { useEffect, useRef } from 'react';
import { X } from 'lucide-react';

interface ModalProps {
    isOpen: boolean;
    onClose: () => void;
    title: string;
    children: React.ReactNode;
}

export function Modal({ isOpen, onClose, title, children }: ModalProps) {
    const overlayRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleEscape = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onClose();
        };

        if (isOpen) {
            document.body.style.overflow = 'hidden';
            window.addEventListener('keydown', handleEscape);
        }

        return () => {
            document.body.style.overflow = 'unset';
            window.removeEventListener('keydown', handleEscape);
        };
    }, [isOpen, onClose]);

    if (!isOpen) return null;

    return (
        <div
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-in fade-in duration-200"
            onClick={(e) => {
                if (e.target === e.currentTarget) onClose();
            }}
        >
            <div className="bg-white dark:bg-zinc-900 rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-200 border border-zinc-200 dark:border-zinc-800">
                <div className="flex items-center justify-between p-4 border-b border-zinc-100 dark:border-zinc-800">
                    <h2 className="text-lg font-semibold text-zinc-900 dark:text-zinc-100">{title}</h2>
                    <button
                        onClick={onClose}
                        className="p-1 rounded-full hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors"
                    >
                        <X size={20} className="text-zinc-500" />
                    </button>
                </div>
                <div className="p-4">
                    {children}
                </div>
            </div>
        </div>
    );
}

'use client';

import { Search, Loader2, LogIn, LogOut, User as UserIcon, ChevronDown, ShieldCheck, Settings, LifeBuoy, ChevronRight } from 'lucide-react';
import { useState, useEffect, useRef } from 'react';
import { auth } from '@/lib/firebase';
import { User, signOut } from 'firebase/auth';
import { LoginModal } from '@/components/LoginModal';
import { cn } from '@/lib/utils';
import { useOnClickOutside } from '@/lib/hooks';
import { isAdmin } from '@/lib/roles';
import { getUserSettings } from '@/app/settings/actions';

interface NavbarProps {
    searchState?: {
        value: string;
        onChange: (val: string) => void;
        onSubmit: () => void;
        loading: boolean;
    };
}
export function Navbar({ searchState }: NavbarProps) {
    const [user, setUser] = useState<User | null>(null);
    const [isUserAdmin, setIsUserAdmin] = useState(false);
    const [dbDisplayName, setDbDisplayName] = useState('');
    const [showLogin, setShowLogin] = useState(false);
    const [showDropdown, setShowDropdown] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    useOnClickOutside(dropdownRef as React.RefObject<HTMLElement>, () => setShowDropdown(false));

    useEffect(() => {
        const fetchUserData = async (email: string) => {
            const adminStatus = await isAdmin(email);
            setIsUserAdmin(adminStatus);

            // Fetch user settings for display name
            const res = await getUserSettings(email);
            if (res.success && res.settings && res.settings.displayName) {
                setDbDisplayName(res.settings.displayName);
            } else {
                setDbDisplayName('');
            }
        };

        const unsubscribe = auth.onAuthStateChanged(async (u) => {
            setUser(u);
            if (u?.email) {
                await fetchUserData(u.email);
            } else {
                setIsUserAdmin(false);
                setDbDisplayName('');
            }
        });

        // Listen for internal settings updates
        const handleSettingsUpdate = () => {
            if (user?.email) {
                fetchUserData(user.email);
            }
        };
        window.addEventListener('user-settings-updated', handleSettingsUpdate);

        return () => {
            unsubscribe();
            window.removeEventListener('user-settings-updated', handleSettingsUpdate);
        };
    }, [user]);

    const handleLogout = async () => {
        await signOut(auth);
        setShowDropdown(false);
    };

    return (
        <>
            <style>{`.custom-dropdown-item:hover { background-color: #2c2c2e !important; }`}</style>
            <nav className={cn(
                "fixed z-50 transition-all duration-300 border-white/10 backdrop-blur-xl flex justify-center",
                searchState
                    ? "top-0 left-0 w-full h-16 border-b bg-black/80"
                    : "top-6 left-1/2 -translate-x-1/2 w-[calc(100%-3rem)] max-w-7xl h-16 rounded-2xl border bg-black/80 shadow-2xl"
            )}>
                {/* INNER CONSTRAINED CONTAINER MATCHING THE REPORT MAX WIDTH */}
                <div className="w-full px-6 h-full flex items-center justify-between gap-6">

                    {/* Logo */}
                    <a href="/" className="text-sm font-medium tracking-widest text-white/90 uppercase opacity-80 hover:opacity-100 transition-opacity shrink-0 select-none cursor-pointer flex items-center">
                        DOMAINGUARD <span className="text-white/30 ml-2">PRO</span>
                    </a>

                    {/* Right Side (Search + Auth) */}
                    <div className="flex flex-1 items-center justify-end gap-6 sm:gap-8">
                        {/* Optional Navbar Search (Visible on Results Page) */}
                        {searchState && (
                            <div className="hidden md:flex items-center relative group w-80 animate-in fade-in slide-in-from-right-4 duration-500">
