import { db } from './firebase';
import { collection, addDoc, query, where, orderBy, limit, getDocs, doc, setDoc } from 'firebase/firestore';

export interface HistoryItem {
    id?: string;
    domain: string;
    score: number;
    timestamp: number;
    status: 'Pass' | 'Warning' | 'Fail';
}

// Save a new scan result
export async function saveScanResult(userId: string, domain: string, score: number) {
    if (!userId) return;

    const data = {
        userId,
        domain,
        score,
        timestamp: Date.now(),
        status: score >= 90 ? 'Pass' : score >= 70 ? 'Warning' : 'Fail'
    };

    // 1. Try Firebase (Best Effort)
    try {
        await addDoc(collection(db, 'scans'), data);
    } catch (error) {
        console.warn("Firebase write failed (likely permission/billing). Falling back to LocalStorage.", error);
    }

    // 2. ALWAYS Save to LocalStorage (Backup)
    try {
        const key = `history_${userId}`;
        const local = JSON.parse(localStorage.getItem(key) || '[]');
        local.unshift(data); // Add to top
        // Keep last 20 locally
        if (local.length > 20) local.pop();
        localStorage.setItem(key, JSON.stringify(local));
    } catch (e) {
        console.error("Local storage failed", e);
    }
}

// Get user History (Combined)
export async function getUserHistory(userId: string): Promise<HistoryItem[]> {
    if (!userId) return [];
    let firebaseDocs: HistoryItem[] = [];
    let localDocs: HistoryItem[] = [];

    // 1. Fetch Firebase
    try {
        const q = query(
            collection(db, 'scans'),
            where('userId', '==', userId),
            orderBy('timestamp', 'desc'),
            limit(10)
        );

        const snapshot = await getDocs(q);
        firebaseDocs = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
        })) as HistoryItem[];
    } catch (error) {
        console.warn("Firebase fetch failed. Serving local only.");
    }

    // 2. Fetch Local
    try {
        const key = `history_${userId}`;
        localDocs = JSON.parse(localStorage.getItem(key) || '[]');
    } catch (e) { }

    // 3. Merge & Deduplicate (Simple approach: Prefer Firebase if ID exists, else Local)
    // Actually, local items won't have 'id' (unless we mock it).
    // Let's just combine and sort.
    const combined = [...firebaseDocs, ...localDocs];

    // Dedupe by timestamp + domain roughly
    const seen = new Set();
    const unique = combined.filter(item => {
        const key = `${item.domain}-${Math.floor(item.timestamp / 1000)}`;
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
    });

    return unique.sort((a, b) => b.timestamp - a.timestamp).slice(0, 20);
}

// Sync User Profile to Firestore (So it appears in Database tab)
export async function saveUserProfile(user: any) {
    if (!user) return;
    try {
        await setDoc(doc(db, "users", user.uid), {
            uid: user.uid,
            email: user.email,
            displayName: user.displayName || '',
            lastLogin: Date.now()
        }, { merge: true });
    } catch (e: any) {
        console.warn("Could not sync user profile to DB", e);
    }
}

import { promises as dnsPromises, MxRecord, SoaRecord, CaaRecord } from 'dns';

// Cache structure: Key -> { promise, timestamp, data }
interface CacheEntry<T> {
    promise: Promise<T>;
    timestamp: number;
    data?: T;
    error?: any;
}

const cache = new Map<string, CacheEntry<any>>();
const TTL = 10 * 60 * 1000; // 10 Minutes

// Global DNS Concurrency Control
// Increased to 128 to prevent queuing delays that cause timeouts on Vercel
const MAX_CONCURRENT_QUERIES = 128;
let runningQueries = 0;
const queryQueue: ((value: void | PromiseLike<void>) => void)[] = [];

async function acquireSlot(): Promise<void> {
    if (runningQueries < MAX_CONCURRENT_QUERIES) {
        runningQueries++;
        return;
    }
    return new Promise(resolve => queryQueue.push(resolve));
}

function releaseSlot(): void {
    runningQueries--;
    if (queryQueue.length > 0) {
        const next = queryQueue.shift();
        if (next) {
            runningQueries++;
            next();
        }
    }
}

/**
 * Generic wrapper to cache DNS calls with global concurrency
 */
async function cachedResolve<T>(
    key: string,
    resolveFn: () => Promise<T>,
    retryCount = 0 // Default to NO retry for bulk speed
): Promise<T> {
    const now = Date.now();
    const headersKey = `DNS:${key}`;

    const entry = cache.get(headersKey);

    // Return valid cached data
    if (entry && (now - entry.timestamp < TTL)) {
        return entry.promise;
    }

    const promise = (async () => {
        let lastError: any;

        for (let attempt = 0; attempt <= retryCount; attempt++) {
            await acquireSlot();

            // TIMEOUT WRAPPER: 2500ms (Strictly optimized for Vercel 10s limit)
            const timeoutPromise = new Promise<never>((_, reject) =>
                setTimeout(() => reject(new Error('DNS Timeout')), 2500)
            );

            try {
                return await Promise.race([resolveFn(), timeoutPromise]);
            } catch (err: any) {
                lastError = err;
                const shouldRetry = attempt < retryCount &&
                    (err.message === 'DNS Timeout' || err.code === 'ETIMEOUT' || err.code === 'ESERVFAIL');

                if (!shouldRetry) throw err;
                await new Promise(resolve => setTimeout(resolve, 300));
            } finally {
                releaseSlot();
            }
        }
        throw lastError;
    })()
        .then(data => {
            cache.set(headersKey, { promise, timestamp: Date.now(), data });
            return data;
        })
        .catch(err => {
            cache.delete(headersKey);
            throw err;
        });

    cache.set(headersKey, { promise, timestamp: now });
    return promise;
}

// Exported wrappers matching used methods
export async function resolve4(hostname: string): Promise<string[]> {
    return cachedResolve(`A:${hostname}`, () => dnsPromises.resolve4(hostname));
}

export async function resolve6(hostname: string): Promise<string[]> {
    return cachedResolve(`AAAA:${hostname}`, () => dnsPromises.resolve6(hostname));
}

export async function resolveMx(hostname: string): Promise<MxRecord[]> {
    return cachedResolve(`MX:${hostname}`, () => dnsPromises.resolveMx(hostname));
}

export async function resolveTxt(hostname: string): Promise<string[][]> {
    return cachedResolve(`TXT:${hostname}`, () => dnsPromises.resolveTxt(hostname));
}

export async function resolveNs(hostname: string): Promise<string[]> {
    return cachedResolve(`NS:${hostname}`, () => dnsPromises.resolveNs(hostname));
}

export async function resolveCname(hostname: string): Promise<string[]> {
    return cachedResolve(`CNAME:${hostname}`, () => dnsPromises.resolveCname(hostname));
}

export async function resolveSoa(hostname: string): Promise<SoaRecord> {
    return cachedResolve(`SOA:${hostname}`, () => dnsPromises.resolveSoa(hostname));
}

export async function resolveCaa(hostname: string): Promise<CaaRecord[]> {
    return cachedResolve(`CAA:${hostname}`, () => dnsPromises.resolveCaa(hostname));
}

// setServers is a dummy/unsupported when using native promises directly for some providers,
// but we keep the export for compatibility if needed.
export const setServers = (servers: string[]) => { /* No-op to avoid breaking Vercel */ };

import { promises as dns } from 'dns';

export interface DnsResult {
    spf: string | null;
    dmarc: string | null;
    dmarcPolicy: string | null;
    mxRecords: string[];
    error?: string;
}

export async function checkDomainDNS(domain: string): Promise<DnsResult> {
    const result: DnsResult = {
        spf: null,
        dmarc: null,
        dmarcPolicy: null,
        mxRecords: [],
    };

    try {
        // SPF Lookup
        const txtRecords = await dns.resolveTxt(domain).catch(() => []);
        // TXT records are arrays of strings (chunks), join them
        const spfRec = txtRecords
            .map((chunks) => chunks.join(''))
            .find((txt) => txt.toLowerCase().startsWith('v=spf1'));

        result.spf = spfRec || null;
    } catch (e) {
        if (e instanceof Error) {
            // Log or handle specific SPF errors if needed
        }
    }

    try {
        // DMARC Lookup
        const dmarcRecords = await dns.resolveTxt(`_dmarc.${domain}`).catch(() => []);
        const dmarcRec = dmarcRecords
            .map((chunks) => chunks.join(''))
            .find((txt) => txt.toLowerCase().startsWith('v=dmarc1'));

        result.dmarc = dmarcRec || null;

        if (dmarcRec) {
            const match = dmarcRec.match(/p=(\w+)/i);
            if (match) {
                result.dmarcPolicy = match[1].toLowerCase();
            }
        }
    } catch (e) {
        // DMARC lookup fail
    }

    try {
        // MX Lookup
        const mx = await dns.resolveMx(domain).catch(() => []);
        result.mxRecords = mx.map((m) => m.exchange);
    } catch (e) {
        // MX lookup fail
    }

    return result;
}

import { resolve4 } from './dns-cache';

export interface BlacklistResult {
    list: string;
    isListed: boolean;
    type: 'IP' | 'DOMAIN';
    target: string;
    details?: string;
    status: 'PASS' | 'FAIL' | 'TIMEOUT' | 'UNKNOWN';
}

// IP Blacklists (11)
export const IP_BLACKLISTS = [
    { name: 'Spamhaus ZEN', host: 'zen.spamhaus.org' },
    { name: 'SpamCop', host: 'bl.spamcop.net' },
    { name: 'Barracuda', host: 'b.barracudacentral.org' },
    { name: 'SORBS (IP)', host: 'dnsbl.sorbs.net' },
    { name: 'PSBL', host: 'psbl.surriel.com' },
    { name: 'UCEPROTECT L1', host: 'dnsbl-1.uceprotect.net' },
    { name: 'DroneBL', host: 'dnsbl.dronebl.org' },
    { name: 'MailSpike BL', host: 'bl.mailspike.net' },
    { name: 'RBL JP', host: 'rbl.jp' },
    { name: 'Anonmails', host: 'spam.dnsbl.anonmails.de' },
    { name: 'Blocklist.de', host: 'bl.blocklist.de' }
];

// Domain Blacklists (8)
export const DOMAIN_BLACKLISTS = [
    { name: 'Spamhaus DBL', host: 'dbl.spamhaus.org' },
    { name: 'SURBL (multi)', host: 'multi.surbl.org' },
    { name: 'SEM FRESH', host: 'fresh.spameatingmonkey.net' },
    { name: 'SEM URI', host: 'uribl.spameatingmonkey.net' },
    { name: 'SEM URIRED', host: 'urired.spameatingmonkey.net' },
    { name: 'ivmURI', host: 'ivmuri.dnsbl.ivmsip.com' },
    { name: 'NordSpam DBL', host: 'dbl.nordspam.com' },
    { name: 'SORBS RHSBL', host: 'rhsbl.sorbs.net' }
];

// 12-hour Cache for Blacklist results
const blCache = new Map<string, { result: boolean, status: any, timestamp: number, details?: string }>();
const BL_TTL = 12 * 60 * 60 * 1000;

/**
 * Normalizes a domain for RHSBL checks (strips leading www. and ensures lowercase)
 */
function normalizeDomain(domain: string): string {
    return domain.toLowerCase().replace(/^www\./, '');
}

async function performLookup(lookupHost: string, listHost: string): Promise<{ isListed: boolean, status: 'PASS' | 'FAIL' | 'UNKNOWN' | 'TIMEOUT', details?: string }> {
    const cacheKey = `${lookupHost}:${listHost}`;
    const cached = blCache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp < BL_TTL)) {
        return { isListed: cached.result, status: cached.status, details: cached.details };
    }

    try {
        // Add random jitter (0-500ms) to spread the load during bulk checks
        await new Promise(resolve => setTimeout(resolve, Math.random() * 500));

        const resultIps = await resolve4(lookupHost);

        // --- PRO-GRADE RETURN CODE HANDLING ---

        // 1. Generic "Service Blocked / Rate Limited" Check
        // Many providers (SEM, SURBL, ivmURI) return 127.0.0.1 to indicate YOUR DNS resolver is blocked.
        // It does NOT mean the target is listed.
        const isCommonBlockedCode = resultIps.includes('127.0.0.1');

        // 2. Spamhaus Specific Blocks
        // 127.255.255.x means the query was refused/blocked by Spamhaus
        const isSpamhausBlocked = listHost.includes('spamhaus.org') &&
            resultIps.some(ip => ip.startsWith('127.255.255.'));

        if (isCommonBlockedCode || isSpamhausBlocked) {
            const details = isSpamhausBlocked ? 'Spamhaus refused query (Rate Limited/Blocked)' : 'Provider refused query (127.0.0.1 - Resolver Blocked)';
            return { isListed: false, status: 'UNKNOWN', details };
        }

        // 3. DNS Wildcard Protection
        // REAL DNSBL results MUST be in the loopback range (127.x.x.x).
        // If it returns anything else (like the domain's own Cloudflare IPs), it's a wildcard "leak".
        const validListingIps = resultIps.filter(ip => ip.startsWith('127.'));
        const isListed = validListingIps.length > 0;

        // CRITICAL: If the result contains ANY non-loopback IP, it's definitely a wildcard leak (Cloudflare/WAF).
        // We reject the entire result as "Clean" in this case.
        const hasWildcardLeak = resultIps.some(ip => !ip.startsWith('127.'));

        if (hasWildcardLeak) {
            return { isListed: false, status: 'PASS' };
        }

        const status = isListed ? 'FAIL' : 'PASS';
        const details = isListed ? `Listed with return code: ${validListingIps.join(', ')}` : undefined;

        blCache.set(cacheKey, { result: isListed, status, timestamp: Date.now(), details });
        return { isListed, status, details };
    } catch (err: any) {
        // ENOTFOUND (NXDOMAIN) = Success (Not listed)
        if (err.code === 'ENOTFOUND' || err.message?.includes('ENOTFOUND')) {
            return { isListed: false, status: 'PASS' };
        }

        // Genuine Timeout
        if (err.message === 'DNS Timeout' || err.code === 'ETIMEOUT') {
            return { isListed: false, status: 'TIMEOUT' };
        }

        // Other errors (SERVFAIL, REFUSED) mean the query failed, not that it's clean
        return { isListed: false, status: 'UNKNOWN', details: `DNS Error: ${err.code || err.message}` };
    }
}

export async function checkIPBlacklist(ip: string): Promise<BlacklistResult[]> {
    const reversedIp = ip.split('.').reverse().join('.');

    return Promise.all(IP_BLACKLISTS.map(async (bl) => {
        const lookup = `${reversedIp}.${bl.host}`;
        const { isListed, status, details } = await performLookup(lookup, bl.host);
        return {
            list: bl.name,
            host: bl.host,
            isListed,
            type: 'IP',
            target: ip,
            status,
            details
        } as any;
    }));
}

export async function checkDomainBlacklist(domain: string): Promise<BlacklistResult[]> {
    const normalized = normalizeDomain(domain);
    return Promise.all(DOMAIN_BLACKLISTS.map(async (bl) => {
        const lookup = `${normalized}.${bl.host}`;
        const { isListed, status, details } = await performLookup(lookup, bl.host);
        return {
            list: bl.name,
            host: bl.host,
            isListed,
            type: 'DOMAIN',
            target: normalized,
            status,
            details
        } as any;
    }));
}

